import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

// Trophy models are generated by scripts/generate-trophies.mjs. iOS Quick Look
// needs USDZ, which model-viewer converts from the GLB on the fly.
export const AR_TIERS = ['gold', 'silver', 'bronze', 'none'];
const trophySrc = (tier) => `/models/trophy-${tier}.glb`;

// Link that reopens this viewer straight away (used for the desktop QR code).
export function arDeepLink(tier, title) {
  const url = new URL(window.location.href);
  url.search = new URLSearchParams({ ar: tier, t: title }).toString();
  url.hash = 'achievements';
  return url.toString();
}

export default function ARTrophyViewer({ tier, title, subtitle, onClose }) {
  const [libReady, setLibReady] = useState(false);
  const [libError, setLibError] = useState(false);
  const [canAR, setCanAR] = useState(null);
  const [arFailed, setArFailed] = useState(false);
  const [qr, setQr] = useState('');
  const viewerRef = useRef(null);
  const closeRef = useRef(null);

  // model-viewer is ~300 KB, so it's only fetched once the viewer is opened.
  useEffect(() => {
    let alive = true;
    import('@google/model-viewer')
      .then(() => alive && setLibReady(true))
      .catch(() => alive && setLibError(true));
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    closeRef.current?.focus();
    return () => { document.body.style.overflow = prevOverflow; };
  }, []);

  // Capture keys before the journey's window listener so arrows don't drive
  // the car behind the modal; Escape closes just this viewer.
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'Escape') onClose();
      if (['Escape', 'Enter', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.stopPropagation();
      }
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [onClose]);

  useEffect(() => {
    const el = viewerRef.current;
    if (!libReady || !el) return undefined;
    const onLoad = () => setCanAR(Boolean(el.canActivateAR));
    const onStatus = (e) => { if (e.detail?.status === 'failed') setArFailed(true); };
    el.addEventListener('load', onLoad);
    el.addEventListener('ar-status', onStatus);
    return () => {
      el.removeEventListener('load', onLoad);
      el.removeEventListener('ar-status', onStatus);
    };
  }, [libReady]);

  // No AR on this device (usually desktop): offer a QR code to open it on a phone.
  useEffect(() => {
    if (canAR !== false) return;
    let alive = true;
    import('qrcode')
      .then((QR) => QR.toDataURL(arDeepLink(tier, title), { margin: 1, width: 360 }))
      .then((data) => alive && setQr(data))
      .catch(() => {});
    return () => { alive = false; };
  }, [canAR, tier, title]);

  return createPortal(
    <div
      className="ar-backdrop"
      onClick={(e) => { e.stopPropagation(); if (e.target === e.currentTarget) onClose(); }}
      onPointerDown={(e) => e.stopPropagation()}
    >
      <div className={`ar-modal tier-${tier}`} role="dialog" aria-modal="true" aria-label={`${title} in AR`}>
        <button ref={closeRef} type="button" className="ar-close" onClick={onClose} aria-label="Close AR viewer">✕</button>

        <div className="ar-head">
          <p className="ar-tag">Augmented reality</p>
          <h3>{title}</h3>
          {subtitle && <p className="ar-sub">{subtitle}</p>}
        </div>

        <div className="ar-stage">
          {libError && <p className="ar-status">Couldn't load the 3D viewer. Please check your connection and try again.</p>}
          {!libError && !libReady && <p className="ar-status">Loading 3D viewer…</p>}
          {libReady && (
            <model-viewer
              ref={viewerRef}
              class="ar-viewer"
              src={trophySrc(tier)}
              alt={`3D trophy for ${title}`}
              ar=""
              ar-modes="webxr scene-viewer quick-look"
              ar-scale="auto"
              ar-placement="floor"
              camera-controls=""
              auto-rotate=""
              touch-action="pan-y"
              camera-orbit="30deg 75deg auto"
              shadow-intensity="1"
              environment-image="neutral"
              exposure="1.1"
            >
              <button slot="ar-button" type="button" className="ar-launch">
                📱 Place it in your room
              </button>
            </model-viewer>
          )}
        </div>

        <div className="ar-foot">
          {canAR && !arFailed && (
            <p>Tap <strong>Place it in your room</strong>, point your camera at the floor or a table, and move your phone slowly until the trophy appears.</p>
          )}
          {arFailed && <p>AR couldn't start on this device. You can still drag to rotate the trophy and pinch to zoom.</p>}
          {canAR === false && (
            <div className="ar-qr">
              {qr && <img src={qr} alt="QR code to open this trophy in AR on your phone" />}
              <p>AR works on phones. Scan this code with an Android or iPhone camera to put this trophy on your desk. Here, you can drag to rotate it.</p>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}
